func validateActionOutput(payload json.RawMessage, contract reflect.Type, actionKey string) error {
	if err := rejectDuplicateActionJSONFields(payload); err != nil {
		return actionOutputError(actionKey, err)
	}
	if err := validateRequiredActionJSON(payload, contract, "$output"); err != nil {
		return actionOutputError(actionKey, err)
	}
	target := reflect.New(contract).Interface()
	decoder := json.NewDecoder(bytes.NewReader(payload))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return actionOutputError(actionKey, err)
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		if err == nil {
			err = errors.New("Action output must contain exactly one JSON value")
		}
		return actionOutputError(actionKey, err)
	}
	return nil
}

func validateRequiredActionJSON(payload json.RawMessage, contract reflect.Type, path string) error {
	for contract.Kind() == reflect.Pointer {
		contract = contract.Elem()
	}
	if contract == reflect.TypeOf(time.Time{}) {
		return nil
	}
	switch contract.Kind() {
	case reflect.Struct:
		var object map[string]json.RawMessage
		if err := json.Unmarshal(payload, &object); err != nil {
			return err
		}
		if object == nil {
			return errors.New(path + " must be a JSON object")
		}
		known := map[string]bool{}
		for index := 0; index < contract.NumField(); index++ {
			field := contract.Field(index)
			tag := strings.Split(field.Tag.Get("json"), ",")
			name := field.Name
			if len(tag) > 0 && tag[0] != "" {
				name = tag[0]
			}
			if name == "-" {
				continue
			}
			known[name] = true
			optional := field.Type.Kind() == reflect.Pointer
			for _, option := range tag[1:] {
				if option == "omitempty" {
					optional = true
				}
			}
			value, exists := object[name]
			if !exists || bytes.Equal(bytes.TrimSpace(value), []byte("null")) {
				if optional {
					continue
				}
				return errors.New(path + "." + name + " is required")
			}
			if err := validateRequiredActionJSON(value, field.Type, path+"."+name); err != nil {
				return err
			}
		}
		for name := range object {
			if !known[name] {
				return errors.New(path + " contains unknown field " + name)
			}
		}
	case reflect.Slice, reflect.Array:
		var values []json.RawMessage
		if err := json.Unmarshal(payload, &values); err != nil {
			return err
		}
		for index, value := range values {
			if err := validateRequiredActionJSON(value, contract.Elem(), path+"["+fmt.Sprint(index)+"]"); err != nil {
				return err
			}
		}
	}
	return nil
}

func rejectDuplicateActionJSONFields(payload json.RawMessage) error {
	decoder := json.NewDecoder(bytes.NewReader(payload))
	var walk func() error
	walk = func() error {
		token, err := decoder.Token()
		if err != nil {
			return err
		}
		delimiter, ok := token.(json.Delim)
		if !ok {
			return nil
		}
		switch delimiter {
		case '{':
			seen := map[string]bool{}
			for decoder.More() {
				keyToken, err := decoder.Token()
				if err != nil {
					return err
				}
				key, ok := keyToken.(string)
				if !ok {
					return errors.New("Action JSON object key must be a string")
				}
				if seen[key] {
					return errors.New("Action JSON contains duplicate field " + key)
				}
				seen[key] = true
				if err := walk(); err != nil {
					return err
				}
			}
			_, err = decoder.Token()
			return err
		case '[':
			for decoder.More() {
				if err := walk(); err != nil {
					return err
				}
			}
			_, err = decoder.Token()
			return err
		default:
			return errors.New("Action JSON contains an unexpected delimiter")
		}
	}
	if err := walk(); err != nil {
		return err
	}
	if _, err := decoder.Token(); err != io.EOF {
		if err == nil {
			return errors.New("Action input must contain exactly one JSON value")
		}
		return err
	}
	return nil
}

